Payload = Annotated[FileSecret, {"description":"Synthetic deployment input"}]
def blueprint(payload: Payload):
    secret = payload
    entry = f'python3 -m pip install --quiet magnus-sdk==0.8.2\npython3 - <<\'LLP_PROBE\'\nimport hashlib,json,os,pathlib,subprocess,shutil,urllib.request\nimport magnus\np=magnus.download_file({secret!r},target_path="/magnus/workspace/payload.txt")\nassert pathlib.Path(p).read_text()=="LLP-AGI deployment roundtrip; no physics events.\\n"\nr={{"success":True,"tool":\'micromegas\',"sdk":magnus.__version__,"physics_events":0}}\nassert json.loads(urllib.request.urlopen(os.environ["MAGNUS_ADDRESS"]+"/health").read())["status"]=="ok"\nassert pathlib.Path("/opt/micromegas_6.3.0").is_dir()\nr["micromegas"]="6.3.0"\nr["compiler"]=subprocess.check_output(["gcc","--version"],text=True).splitlines()[0]\nout=pathlib.Path("/magnus/workspace/probe.json")\nout.write_text(json.dumps(r,indent=2))\nsecret=magnus.custody_file(str(out),max_downloads=3)\npathlib.Path(os.environ["MAGNUS_RESULT"]).write_text(json.dumps({{"success":True,"output":secret}}))\n\nLLP_PROBE'
    submit_job(task_name="Deployment probe micromegas", namespace="HET-AGI", repo_name="ColliderAgent", branch="main", commit_sha="1140f39e8730889422a64a141fbd3ca10529e13b", container_image="docker://git.pku.edu.cn/rise-agi/micromegas@sha256:070498baf78f4efc29a48ba67d0eaec2730af006b386a2d7c9047f65a123e62a", cpu_count=4, memory_demand="8G", system_entry_command='', entry_command=entry)
